def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 5 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))
                for nr, nc in ((rr-1, cc), (rr+1, cc), (rr, cc-1), (rr, cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 5 and (nr, nc) not in seen:
                        seen.add((nr, nc))
                        stack.append((nr, nc))
            r0, r1 = min(x for x, _ in cells), max(x for x, _ in cells)
            c0, c1 = min(y for _, y in cells), max(y for _, y in cells)
            # Fill the object's missing cells; its sole top-edge gap is the exit.
            openings = [c for c in range(c0, c1 + 1) if grid[r0][c] == 0]
            for rr in range(r0, r1 + 1):
                for cc in range(c0, c1 + 1):
                    if grid[rr][cc] == 0:
                        out[rr][cc] = 2
            if openings and r0 > 0:
                for cc in range(0, openings[0] + 1):
                    if out[r0 - 1][cc] == 0:
                        out[r0 - 1][cc] = 2
    return out

